// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const body = $json.body || {};
const query = $json.query || {};

const company_id = body.company_id || query.company_id;
const start_date = body.start_date || query.start_date;
const end_date = body.end_date || query.end_date;
const response_format = body.response_format || query.response_format || "json";

if (!company_id) {
  return [{
    json: {
      success: false,
      error: "Missing required parameter: company_id"
    }
  }];
}

if (!start_date) {
  return [{
    json: {
      success: false,
      error: "Missing required parameter: start_date"
    }
  }];
}

if (!end_date) {
  return [{
    json: {
      success: false,
      error: "Missing required parameter: end_date"
    }
  }];
}

return [{
  json: {
    success: true,
    company_id: parseInt(company_id),
    start_date,
    end_date,
    response_format,
    invoice_filters: [
      ["move_type", "in", ["out_invoice", "out_refund"]],
      ["state", "=", "posted"],
      ["invoice_date", ">=", start_date],
      ["invoice_date", "<=", end_date],
      ["company_id", "=", parseInt(company_id)]
    ]
  }
}];

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function safeJsonParse(value) {
  if (!value) return null;
  if (typeof value === "object") return value;

  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

function normalisePayload(raw) {
  const item = Array.isArray(raw) ? raw[0] : raw;
  return item?.body?.data || item?.data || item;
}

function secondsToClock(seconds = 0) {
  const safe = Number(seconds || 0);
  const mins = Math.floor(safe / 60);
  const secs = safe % 60;
  return `${mins}:${String(secs).padStart(2, "0")}`;
}

function formatDate(value, timezone = "Australia/Brisbane") {
  if (!value) return "Not supplied";

  const date = typeof value === "number"
    ? new Date(value * 1000)
    : new Date(value);

  if (Number.isNaN(date.getTime())) return String(value);

  return new Intl.DateTimeFormat("en-AU", {
    timeZone: timezone,
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit"
  }).format(date);
}

function getCustomerName(data) {
  const transcript = asArray(data.transcript);

  const firstUserMessage =
    transcript.find((turn) => turn.role === "user" && turn.message)?.message || "";

  const nameMatch = firstUserMessage.match(/my name is\s+([^,.!?]+)/i);
  if (nameMatch?.[1]) return nameMatch[1].trim();

  const summary = data.analysis?.transcript_summary || "";
  const summaryMatch = summary.match(/user,\s*([^,]+),/i);
  if (summaryMatch?.[1]) return summaryMatch[1].trim();

  return "Customer not identified";
}

function walkToolResults(value, output = []) {
  if (!value) return output;

  if (Array.isArray(value)) {
    for (const item of value) walkToolResults(item, output);
    return output;
  }

  if (typeof value !== "object") return output;

  if (value.tool_name) output.push(value);

  walkToolResults(value.result, output);
  walkToolResults(value.results, output);
  walkToolResults(value.steps, output);
  walkToolResults(value.tool_results, output);

  return output;
}

function summariseParams(params) {
  if (!params) return "No parameters supplied";

  if (typeof params === "string") {
    return params.slice(0, 220);
  }

  if (params.function && params.payload) {
    return `${params.function}: ${JSON.stringify(params.payload)}`;
  }

  return JSON.stringify(params).slice(0, 220);
}

function summariseToolResult(result) {
  if (!result) return "No result payload supplied";

  if (result.result_type === "transfer_to_agent_success" || result.status === "success") {
    return "Workflow transfer completed successfully.";
  }

  if (result.success === true && result.operation === "job_search") {
    const count = result.data?.count ?? result.data?.job_cards?.length ?? "multiple";
    return `HubTiger job search completed. ${count} job cards returned.`;
  }

  if (result.success === true && result.operation === "job_retrieve") {
    const card =
      result.data?.job_cards?.[0] ||
      result.data?.results?.[0] ||
      result.data?.matches?.[0];

    if (card) {
      const jobCardNo = card.job_card_no || card.jobCardNo || "selected job";
      const vehicle = card.bike || "vehicle not supplied";
      const status = card.statusLabel || card.status || "status not supplied";
      return `Retrieved ${jobCardNo} for ${vehicle}; status ${status}.`;
    }

    return "HubTiger job retrieve completed.";
  }

  if (typeof result === "string") return result.slice(0, 220);

  return JSON.stringify(result).slice(0, 220);
}

function extractToolEvents(data) {
  const transcript = asArray(data.transcript);
  const events = [];

  for (const turn of transcript) {
    for (const call of turn.tool_calls || []) {
      events.push({
        time: secondsToClock(turn.time_in_call_secs || 0),
        name: call.tool_name || "Unknown tool",
        phase: "Called",
        status: call.tool_has_been_called === false ? "Issue" : "OK",
        result: summariseParams(safeJsonParse(call.params_as_json) || call.params_as_json),
        raw: call
      });
    }

    const flatResults = walkToolResults(turn.tool_results || []);

    for (const result of flatResults) {
      const parsedResult =
        safeJsonParse(result.result_value) ||
        result.result ||
        result.result_value ||
        null;

      events.push({
        time: secondsToClock(turn.time_in_call_secs || 0),
        name: result.tool_name || "Unknown tool",
        phase: "Result",
        status: result.is_error || result.is_blocked ? "Issue" : "OK",
        result: summariseToolResult(parsedResult),
        raw: result
      });
    }
  }

  const seen = new Set();

  return events.filter((event) => {
    const key = `${event.time}|${event.name}|${event.phase}|${event.status}|${event.result}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function collectJobCards(data) {
  const events = extractToolEvents(data);
  const cards = [];

  for (const event of events) {
    const raw = event.raw;
    const parsed =
      safeJsonParse(raw?.result_value) ||
      raw?.result ||
      null;

    const jobCards =
      parsed?.data?.job_cards ||
      parsed?.data?.results ||
      parsed?.data?.matches ||
      [];

    if (!Array.isArray(jobCards)) continue;

    for (const card of jobCards) {
      const jobCardNo = card.job_card_no || card.jobCardNo;
      if (!jobCardNo) continue;

      cards.push({
        jobCardNo,
        customerName: card.customer_name || card.customerName || "",
        vehicle: card.bike || "",
        status: card.statusLabel || card.status_label || card.status || "",
        scheduledDate: card.scheduled_date || card.scheduledDate || "",
        lastUpdated: card.last_updated || card.lastUpdated || ""
      });
    }
  }

  const byNo = new Map();
  for (const card of cards) byNo.set(card.jobCardNo, card);

  return Array.from(byNo.values());
}

function getSelectedJob(data, jobCards) {
  const retrieveEvent = extractToolEvents(data).find(
    (event) => event.name?.includes("job_retrieve") && event.phase === "Result"
  );

  const parsed =
    safeJsonParse(retrieveEvent?.raw?.result_value) ||
    retrieveEvent?.raw?.result ||
    null;

  const card =
    parsed?.data?.job_cards?.[0] ||
    parsed?.data?.results?.[0] ||
    parsed?.data?.matches?.[0];

  const selected = card
    ? {
        jobCardNo: card.job_card_no || card.jobCardNo,
        customerName: card.customer_name || card.customerName,
        vehicle: card.bike,
        status: card.statusLabel || card.status_label || card.status,
        scheduledDate: card.scheduled_date || card.scheduledDate,
        lastUpdated: card.last_updated || card.lastUpdated
      }
    : jobCards.find((job) => job.jobCardNo === "#24433") || jobCards[0] || {};

  return {
    jobCardNo: selected.jobCardNo || "Not confirmed",
    customerName: selected.customerName || "",
    vehicle: selected.vehicle || "Not supplied",
    status: selected.status || "Not supplied",
    scheduledDate: selected.scheduledDate || "",
    lastUpdated: selected.lastUpdated || ""
  };
}

function getNotesStatement(data) {
  const transcript = asArray(data.transcript);

  const notesTurn = transcript.find((turn) =>
    /no customer-facing notes/i.test(turn.message || "")
  );

  if (notesTurn?.message) return notesTurn.message;

  return "No customer-facing notes were identified in the call transcript.";
}

function renderToolsHtml(tools) {
  if (!tools.length) {
    return `<p style="margin:0;color:#667085;font-size:14px;">No tools were called.</p>`;
  }

  return `
    <table width="100%" cellspacing="0" cellpadding="0" border="0" style="border-collapse:collapse;background:#ffffff;">
      <thead>
        <tr>
          <th align="left" style="padding:9px;border-bottom:1px solid #d9e1ea;font-size:11px;color:#475467;text-transform:uppercase;">Time</th>
          <th align="left" style="padding:9px;border-bottom:1px solid #d9e1ea;font-size:11px;color:#475467;text-transform:uppercase;">Tool</th>
          <th align="left" style="padding:9px;border-bottom:1px solid #d9e1ea;font-size:11px;color:#475467;text-transform:uppercase;">Phase</th>
          <th align="left" style="padding:9px;border-bottom:1px solid #d9e1ea;font-size:11px;color:#475467;text-transform:uppercase;">Result</th>
        </tr>
      </thead>
      <tbody>
        ${tools.map((tool) => `
          <tr>
            <td style="padding:9px;border-bottom:1px solid #d9e1ea;font-size:13px;font-family:Consolas,monospace;">${escapeHtml(tool.time)}</td>
            <td style="padding:9px;border-bottom:1px solid #d9e1ea;font-size:13px;font-weight:bold;">${escapeHtml(tool.name)}</td>
            <td style="padding:9px;border-bottom:1px solid #d9e1ea;font-size:13px;">${escapeHtml(tool.phase)}</td>
            <td style="padding:9px;border-bottom:1px solid #d9e1ea;font-size:13px;">${escapeHtml(tool.status)} — ${escapeHtml(tool.result)}</td>
          </tr>
        `).join("")}
      </tbody>
    </table>
  `;
}

function renderJobCardsHtml(jobCards, timezone) {
  if (!jobCards.length) {
    return `<p style="margin:0;color:#667085;font-size:14px;">No job cards were returned.</p>`;
  }

  return `
    <table width="100%" cellspacing="0" cellpadding="0" border="0" style="border-collapse:collapse;background:#ffffff;">
