function renderTranscriptHtml(data) {
  const transcript = asArray(data.transcript).filter((turn) => turn.message);

  if (!transcript.length) {
    return `<p style="margin:0;color:#667085;font-size:14px;">No transcript was supplied.</p>`;
  }

  return transcript.map((turn) => {
    const speaker =
      turn.role === "agent"
        ? data.agent_name || "Magic Mike"
        : turn.role === "user"
          ? "Customer"
          : turn.role || "System";

    return `
      <div style="border:1px solid #d9e1ea;border-radius:10px;background:#ffffff;padding:11px 13px;margin-bottom:9px;">
        <div style="font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#667085;font-weight:bold;margin-bottom:5px;">
          ${escapeHtml(secondsToClock(turn.time_in_call_secs || 0))} — ${escapeHtml(speaker)}
        </div>
        <div style="font-size:14px;line-height:1.55;color:#111827;">
          ${escapeHtml(turn.message)}
        </div>
      </div>
    `;
  }).join("");
}

function buildTranscriptText(data) {
  return asArray(data.transcript)
    .filter((turn) => turn.message)
    .map((turn) => {
      const speaker =
        turn.role === "agent"
          ? data.agent_name || "Magic Mike"
          : turn.role === "user"
            ? "Customer"
            : turn.role || "System";

      return `[${secondsToClock(turn.time_in_call_secs || 0)}] ${speaker}: ${turn.message}`;
    })
    .join("\n");
}

