if (!templateData || typeof templateData !== 'object') {
  throw new Error(
    'Clean ElevenLabs Call did not output templateData/templateDataJson. Check the Clean node output.'
  );
}

// SES GetTemplate output can vary depending on n8n/AWS node wrapping.
const root = Array.isArray(sesInput) ? sesInput[0] : sesInput;

const template =
  root.GetTemplateResult?.Template ||
  root.Template ||
  root.template ||
  ((root.SubjectPart || root.HtmlPart || root.TextPart) ? root : null);

if (!template) {
  throw new Error(
    `SES template not found in GetTemplate output. Available keys: ${Object.keys(root || {}).join(', ')}`
  );
}

const defaults = {
  agentName: 'Magic Mike',
  customerName: 'Customer not identified',

  callTitle: 'Workshop Repair Inquiry',
  callOutcome: 'Not supplied',
