  ...templateData,
};

const missingTemplateKeys = new Set();

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function getValue(obj, path) {
  return path.split('.').reduce((acc, part) => {
    if (acc === undefined || acc === null) return undefined;
    return acc[part];
  }, obj);
}

function renderTemplate(str, data) {
  if (!str) return '';

  return String(str)
    // Raw HTML placeholders. Use these for toolsHtml, jobCardsHtml, transcriptHtml.
    .replace(/\{\{\{\s*([\w.]+)\s*\}\}\}/g, (_, key) => {
      const value = getValue(data, key);
      if (value === undefined || value === null) {
        missingTemplateKeys.add(key);
        return '';
      }
      return String(value);
    })

    // Escaped normal placeholders.
    .replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, key) => {
      const value = getValue(data, key);
      if (value === undefined || value === null) {
        missingTemplateKeys.add(key);
        return '';
      }
      return escapeHtml(value);
    });
}

function stripHtml(html) {
  return String(html ?? '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|h1|h2|h3|h4|h5|h6)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const subject = renderTemplate(
  template.SubjectPart || 'Magic Mike call report — {{customerName}} — {{callTitle}}',
  vars
);

const html = renderTemplate(template.HtmlPart || '', vars);

if (!html) {
  throw new Error('Rendered HTML is empty. Check the SES template HtmlPart.');
}

const text =
  renderTemplate(template.TextPart || '', vars) ||
  stripHtml(html);

return [
  {
    json: {
      templateName: template.TemplateName || root.TemplateName || 'unknown-template',
      subject,
      html,
      text,
      variables: vars,
      missingTemplateKeys: Array.from(missingTemplateKeys),
    },
  },
];

