/**
 * n8n Code node
 * Workflow: ElevenLabs post-call -> cleaned summary email -> optional callback task
 *
 * Input expected:
 * - ElevenLabs post_call_transcription webhook payload
 *
 * Output fields:
 * - subject
 * - emailHtml
 * - plainTextSummary
 * - callbackRequired
 * - taskTitle
 * - taskBody
 * - customerName
 * - callerNumberFormatted
 * - primaryJob
 * - jobCards
 * - cleanTranscript
 */

function safeGet(obj, path, fallback = null) {
  try {
    return path.split('.').reduce((acc, key) => {
      if (acc === undefined || acc === null) return undefined;
      return acc[key];
    }, obj) ?? fallback;
  } catch {
    return fallback;
  }
}

function asArray(value) {
  return Array.isArray(value) ? value : value ? [value] : [];
}

function stripVoiceTags(text) {
  if (!text) return '';
  return String(text)
    .replace(/\[(Patient|Enthusiastically|Calmly|Warmly|Cheerfully|Professionally|Friendly|Neutral)\]\s*/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function htmlEscape(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

function formatPhoneAU(phone) {
  if (!phone) return '';
  const s = String(phone).replace(/\s+/g, '');
  if (s.startsWith('+61')) {
    const rest = s.slice(3);
    if (rest.length === 9) {
      return `0${rest.slice(0, 3)} ${rest.slice(3, 6)} ${rest.slice(6)}`;
    }
  }
  return phone;
}

function formatDateTimeBrisbane(isoOrUnix) {
  if (!isoOrUnix) return '';
  let d;

  if (typeof isoOrUnix === 'number') {
    d = new Date(isoOrUnix * 1000);
  } else {
    d = new Date(isoOrUnix);
  }

  if (Number.isNaN(d.getTime())) return String(isoOrUnix);

  return new Intl.DateTimeFormat('en-AU', {
    timeZone: 'Australia/Brisbane',
    weekday: 'short',
    year: 'numeric',
    month: 'short',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(d);
}

function secondsToDuration(seconds) {
  const n = Number(seconds || 0);
  const m = Math.floor(n / 60);
  const s = n % 60;
  if (m <= 0) return `${s}s`;
  return `${m}m ${s}s`;
}

function tryParseJson(value) {
  if (!value || typeof value !== 'string') return null;
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

function parseNestedToolResults(transcript) {
  const parsed = {
    jobCards: [],
    hubTigerOperations: [],
    rawToolSummaries: [],
  };

  for (const turn of asArray(transcript)) {
    for (const result of asArray(turn.tool_results)) {
      const top = tryParseJson(result.result_value);
      if (!top) continue;

      const steps = asArray(top.steps);
      for (const step of steps) {
        const nestedResults = asArray(step.results);
        for (const nested of nestedResults) {
          const nestedValue = tryParseJson(nested.result_value);
          if (!nestedValue) continue;

          if (nested.tool_name) {
            parsed.rawToolSummaries.push({
              tool: nested.tool_name,
              is_error: nested.is_error,
              operation: nestedValue.operation || '',
              message: nestedValue.message || '',
            });
          }

          const data = nestedValue.data || {};
          const cards = data.job_cards || data.matches || data.results || [];
          if (Array.isArray(cards) && cards.length) {
            for (const card of cards) {
              const normalized = {
                id: card.id ?? null,
                jobCardNo: card.jobCardNo || card.job_card_no || '',
                customerName: card.customerName || card.customer_name || '',
                bike: card.bike || '',
                status: card.statusLabel || card.status || '',
                statusCode: card.statusCode || card.status_code || '',
                scheduledDate: card.scheduledDate || card.scheduled_date || '',
                lastUpdated: card.lastUpdated || card.last_updated || '',
                label: card.label || '',
              };

              const dedupeKey = `${normalized.id}|${normalized.jobCardNo}`;
              if (!parsed.jobCards.some(x => `${x.id}|${x.jobCardNo}` === dedupeKey)) {
                parsed.jobCards.push(normalized);
              }
            }
          }

          if (nestedValue.operation) {
            parsed.hubTigerOperations.push(nestedValue.operation);
          }
        }
      }
    }
  }

  return parsed;
}

function cleanTranscript(transcript) {
  return asArray(transcript)
    .filter(t => t && (t.message || t.original_message || asArray(t.tool_calls).length || asArray(t.tool_results).length))
    .map(t => {
      const role = t.role === 'agent' ? 'Agent' : t.role === 'user' ? 'Caller' : String(t.role || 'Unknown');
      const message = stripVoiceTags(t.message || t.original_message || '');
      return {
        role,
        message,
        timeInCallSecs: t.time_in_call_secs ?? null,
        interrupted: Boolean(t.interrupted),
        toolCalls: asArray(t.tool_calls).map(tc => tc.tool_name).filter(Boolean),
      };
    })
    .filter(t => t.message || t.toolCalls.length);
}

function inferCallbackRequired({ cleanTurns, summary }) {
  const fullText = [
    summary,
    ...cleanTurns.map(t => t.message),
  ].join(' ').toLowerCase();

  const lastUserTurn = [...cleanTurns].reverse().find(t => t.role === 'Caller');
  const lastAgentTurn = [...cleanTurns].reverse().find(t => t.role === 'Agent');

  const callerAskedAvailability = Boolean(lastUserTurn?.message?.toLowerCase().includes('availability'));
  const agentAskedClarifyingQuestion = Boolean(lastAgentTurn?.message?.toLowerCase().includes('could you please confirm'));

  const unresolvedSignals = [
    'check the availability',
    'availability',
    'book a new appointment',
    'current scheduled',
    'call ended',
    'ended by remote party',
    'not resolved',
    'follow up',
    'callback',
    'call back',
  ];

  const hasUnresolvedSignal = unresolvedSignals.some(s => fullText.includes(s));

  return Boolean(callerAskedAvailability || agentAskedClarifyingQuestion || hasUnresolvedSignal);
}

function choosePrimaryJob(jobCards, cleanTurns) {
  if (!jobCards.length) return null;

  const text = cleanTurns.map(t => t.message).join(' ').toLowerCase();

  const apexCards = jobCards.filter(card =>
    String(card.bike || '').toLowerCase().includes('apex') ||
    String(card.bike || '').toLowerCase().includes('vsett')
  );

  if (text.includes('apex') || text.includes('reset') || text.includes('vsett')) {
    const sorted = apexCards
      .slice()
      .sort((a, b) => new Date(b.scheduledDate || 0) - new Date(a.scheduledDate || 0));
    if (sorted.length) return sorted[0];
  }

  return jobCards[0];
}

